new = load('/tmp/eval-work-yd15ZA/renewal.py','new')

statuses = ['banned','active','lapsed','suspended','weird', None, 123]
tiers = ['basic','gold','premium', None, 123]
ids = ['abc','',None,123]
methods = ['card','transfer','cash',None,123]
amounts = [0,1,39,40,41,55,56,64,65,66,79,80,90,120,-5,None,1.5,'x',True]
expireds = [0,30,31,45,-1,None,1.5,'x']
strikes = [0,1,2,3,4,-1,None,1.5,'x']

def mk(status, tier, mid, method, amount, expired=None, strikes_=None):
    m = {"id": mid, "status": status, "tier": tier}
    if status=='lapsed' and expired is not None:
        m["expired_days"]=expired
    if status=='suspended' and strikes_ is not None:
        m["strikes"]=strikes_
    if status=='lapsed' and expired is None:
        pass
    if status=='suspended' and strikes_ is None:
        pass
    p = {"amount": amount, "method": method}
    return m,p

mismatch=0; total=0
# variants
for status in statuses:
  for tier in tiers:
    for mid in ids:
      for method in methods:
        for amount in amounts:
          for expired in expireds:
            for st in strikes:
              total+=1
              m,p = mk(status,tier,mid,method,amount,expired,st)
              try: r1=orig.process_renewal(copy.deepcopy(m),copy.deepcopy(p))
              except Exception as e: r1=('EXC',type(e).__name__)
              try: r2=new.process_renewal(copy.deepcopy(m),copy.deepcopy(p))
              except Exception as e: r2=('EXC',type(e).__name__)
              if r1!=r2:
                mismatch+=1
                if mismatch<=30:
                  print("MISMATCH",m,p, r1,'VS',r2)
# non-dict inputs
for a in [None,1,'x',[],[{}]]:
  for b in [None,{},1,'x']:
    total+=1
    r1=orig.process_renewal(a,b); r2=new.process_renewal(a,b)
    if r1!=r2:
      mismatch+=1; print("MSM",a,b,r1,r2)
print("total",total,"mismatch",mismatch)
